INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','stative-dynamic','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"stative-dynamic","title":"States and actions: simple or continuous?","level":"B1","order":30,"summary":"Choose a verb form from its meaning: a state, an activity or a temporary behaviour.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["States are not normally continuous","A verb can change meaning","Temporary behaviour with being","Perception and deliberate activity"],"rules":[{"title":"States are not normally continuous","explanation":"Know, believe, own and need commonly describe states rather than activities unfolding moment by moment. They usually take simple forms even when true now. A word such as now does not force every verb into the continuous.","pattern":"I **know** the answer now.","commonMistakes":["I am knowing the answer is not the ordinary standard form for possession of knowledge."],"examples":["Describe present knowledge: “I **know** how to prepare the visitor guide.”","Describe present knowledge: “I **know** how to restore the old portrait.”"],"skill":"form"},{"title":"A verb can change meaning","explanation":"Think can mean hold an opinion or actively consider. Have can mean possess or take part in an activity. Use the meaning in the sentence to decide whether continuous aspect is natural.","pattern":"I **think** it is useful. / I **am thinking about** the problem.","commonMistakes":["A memorised list of stative verbs is not enough: the same spelling can have a dynamic sense."],"examples":["Use present continuous for active consideration: “We **are thinking** about how to prepare the visitor guide.”","Use present continuous for active consideration: “We **are thinking** about how to restore the old portrait.”"],"skill":"meaning"},{"title":"Temporary behaviour with being","explanation":"Be usually describes a state, but **be being + adjective** can describe temporary behaviour. You are being helpful comments on someone’s behaviour now. It does not mean that every adjective works naturally in this pattern.","pattern":"He **is being patient** today.","commonMistakes":["He is being tall does not normally describe temporary behaviour; height is a characteristic."],"examples":["State an opinion, in the simple present: “She **thinks** that preparing the visitor guide is worthwhile.”","State an opinion, in the simple present: “She **thinks** that restoring the old portrait is worthwhile.”"],"skill":"contrast"},{"title":"Perception and deliberate activity","explanation":"See and hear often describe involuntary perception and use simple forms or can. Other senses can describe deliberate activity: tasting soup or smelling a flower. See can also mean meet, which permits a continuous arrangement.","pattern":"I **can hear** music. / She **is tasting** the soup.","commonMistakes":["Advertising and informal emphatic uses sometimes put state verbs in the continuous. Practice here follows the ordinary meaning stated in each prompt."],"examples":["Comment on temporary helpful behaviour: “You **are being** helpful by preparing the visitor guide for us today.”","Comment on temporary helpful behaviour: “You **are being** helpful by restoring the old portrait for us today.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-stative"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"f4af243e-da66-5d7e-ab47-144eb7fcd1b5","topicSlug":"stative-dynamic","level":"B1","prompt":"Describe present knowledge: “I ____ how to prepare the visitor guide.”","choices":[{"id":"A","text":"am know"},{"id":"B","text":"know"},{"id":"C","text":"am knowing"},{"id":"D","text":"knowing"}],"answerId":"B","hint":"The sentence expresses **knowledge**, not an activity in progress.","explanation":"Knowledge is a state in this sentence, so the ordinary form is **know**.","keywords":["knowledge-state"],"skill":"knowledge-state","contextKey":"stative-dynamic-1","fingerprint":"e5e2c898099dec568ca9d302211eda48a0fbda1788a3d03f92e5ae8c977c9681","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-stative"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The sentence expresses **knowledge**, not an activity in progress.","Knowledge is a state in this sentence, so the ordinary form is **know**.","Choose **know**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Am cannot directly take the base verb know here.","B":"Knowledge is a state in this sentence, so the ordinary form is **know**.","C":"The ordinary possession-of-knowledge sense does not use continuous aspect.","D":"An -ing form alone is not a finite verb."}}},{"id":"5b5a0bfe-c496-52d6-a2e5-dc6bbc6d94a9","topicSlug":"stative-dynamic","level":"B1","prompt":"Use present continuous for active consideration: “We ____ about how to prepare the visitor guide.”","choices":[{"id":"A","text":"is thinking"},{"id":"B","text":"are thinking"},{"id":"C","text":"are think"},{"id":"D","text":"thinking"}],"answerId":"B","hint":"Thinking about an issue is an **activity**; build the requested continuous form.","explanation":"Active consideration is dynamic: **are thinking about**.","keywords":["active-consideration"],"skill":"active-consideration","contextKey":"stative-dynamic-1","fingerprint":"3a25eb408aeff66516c4bbf9960f5c88aa9428e297a8ec2ee84c80624a4336d1","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-stative"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Thinking about an issue is an **activity**; build the requested continuous form.","Active consideration is dynamic: **are thinking about**.","Choose **are thinking**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Is does not agree with we.","B":"Active consideration is dynamic: **are thinking about**.","C":"The continuous requires thinking after are.","D":"The finite auxiliary are is missing."}}},{"id":"0ffe8f61-0609-5f7d-ae67-e63d28024e62","topicSlug":"stative-dynamic","level":"B1","prompt":"State an opinion, in the simple present: “She ____ that preparing the visitor guide is worthwhile.”","choices":[{"id":"A","text":"is think"},{"id":"B","text":"thinking"},{"id":"C","text":"thinks"},{"id":"D","text":"think"}],"answerId":"C","hint":"Think followed by **that + proposition** expresses an opinion in this example.","explanation":"Think here means **hold an opinion**, so use simple present thinks with she.","keywords":["opinion-state"],"skill":"opinion-state","contextKey":"stative-dynamic-1","fingerprint":"4e977508083960ad6957471675402ce096757ffb05d0b62bd73ded4c89be48a5","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-stative"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Think followed by **that + proposition** expresses an opinion in this example.","Think here means **hold an opinion**, so use simple present thinks with she.","Choose **thinks**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Be cannot take base think in this statement.","B":"Thinking alone has no finite tense or subject agreement.","C":"Think here means **hold an opinion**, so use simple present thinks with she.","D":"The third-person singular subject requires thinks."}}},{"id":"faad7cdf-009e-5751-a06f-defedb0fa091","topicSlug":"stative-dynamic","level":"B1","prompt":"Comment on temporary helpful behaviour: “You ____ helpful by preparing the visitor guide for us today.”","choices":[{"id":"A","text":"are being"},{"id":"B","text":"is being"},{"id":"C","text":"are be"},{"id":"D","text":"being"}],"answerId":"A","hint":"The adjective describes **behaviour today**, so temporary being is appropriate.","explanation":"**Are being helpful** describes the person’s behaviour in this situation.","keywords":["temporary-behaviour"],"skill":"temporary-behaviour","contextKey":"stative-dynamic-1","fingerprint":"bfcb8e211d06805bf56545db66e0833bd57a4f6ba5d6e91c0fa0d8e0c6c2b899","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-stative"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The adjective describes **behaviour today**, so temporary being is appropriate.","**Are being helpful** describes the person’s behaviour in this situation.","Choose **are being**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Are being helpful** describes the person’s behaviour in this situation.","B":"Is does not agree with you.","C":"The continuous of be requires being after are.","D":"A finite auxiliary is missing."}}},{"id":"73943a98-d8e7-5011-aff0-9519813e2da5","topicSlug":"stative-dynamic","level":"B1","prompt":"Describe present knowledge: “I ____ how to restore the old portrait.”","choices":[{"id":"A","text":"am knowing"},{"id":"B","text":"knowing"},{"id":"C","text":"am know"},{"id":"D","text":"know"}],"answerId":"D","hint":"The sentence expresses **knowledge**, not an activity in progress.","explanation":"Knowledge is a state in this sentence, so the ordinary form is **know**.","keywords":["knowledge-state"],"skill":"knowledge-state","contextKey":"stative-dynamic-2","fingerprint":"b92e33838e8ef01a2c40fe76cc9381665268f32d28b1e8dff48dff71f7408f17","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-stative"],"version"